// webgpu.h bindings (emdawnwebgpu), generated by `just generate-webgpu-bindings` into
// sys/generated.rs, plus the #define constants bindgen can't evaluate and a
// few helpers.
//
// The functions only exist on Emscripten (`--use-port=emdawnwebgpu` links
// them). Elsewhere `webgpu_functions!` turns every declaration into a stub
// that panics, so native builds type-check this crate without referencing
// undefined wgpu* symbols. Nothing calls the stubs: the backend is only
// instantiated on Emscripten (mln_webgpu's instance hook).

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all,
    reason = "generated webgpu.h bindings keep the C names"
)]

macro_rules! webgpu_functions {
    ($(pub fn $name:ident($($arg:ident: $ty:ty),* $(,)?) $(-> $ret:ty)?;)*) => {
        #[cfg(target_os = "emscripten")]
        unsafe extern "C" {
            $(pub fn $name($($arg: $ty),*) $(-> $ret)?;)*
        }
        $(
            #[cfg(not(target_os = "emscripten"))]
            #[allow(unused_variables, clippy::missing_safety_doc)]
            pub unsafe fn $name($($arg: $ty),*) $(-> $ret)? {
                crate::sys::unavailable(stringify!($name))
            }
        )*
    };
}

#[cfg(not(target_os = "emscripten"))]
#[cold]
pub(crate) fn unavailable(name: &str) -> ! {
    panic!("mln_wgpu_webgpu_h: {name} is only available on Emscripten (--use-port=emdawnwebgpu)")
}

#[rustfmt::skip]
mod generated;
pub use generated::*;

// The #defines of webgpu.h.
pub const WGPU_TRUE: WGPUBool = 1;
pub const WGPU_FALSE: WGPUBool = 0;
pub const WGPU_ARRAY_LAYER_COUNT_UNDEFINED: u32 = u32::MAX;
pub const WGPU_COPY_STRIDE_UNDEFINED: u32 = u32::MAX;
pub const WGPU_DEPTH_CLEAR_VALUE_UNDEFINED: f32 = f32::NAN;
pub const WGPU_DEPTH_SLICE_UNDEFINED: u32 = u32::MAX;
pub const WGPU_LIMIT_U32_UNDEFINED: u32 = u32::MAX;
pub const WGPU_LIMIT_U64_UNDEFINED: u64 = u64::MAX;
pub const WGPU_MIP_LEVEL_COUNT_UNDEFINED: u32 = u32::MAX;
pub const WGPU_QUERY_SET_INDEX_UNDEFINED: u32 = u32::MAX;
pub const WGPU_STRLEN: usize = usize::MAX;
pub const WGPU_WHOLE_MAP_SIZE: usize = usize::MAX;
pub const WGPU_WHOLE_SIZE: u64 = u64::MAX;

/// The null string (`WGPU_STRING_VIEW_INIT`).
pub const NULL_STRING: WGPUStringView = WGPUStringView { data: core::ptr::null(), length: WGPU_STRLEN };

/// A borrowed, not NUL-terminated string view. The caller keeps `s` alive
/// for as long as the view is used.
pub fn string_view(s: &str) -> WGPUStringView {
    WGPUStringView { data: s.as_ptr().cast(), length: s.len() }
}

pub fn label(label: Option<&str>) -> WGPUStringView {
    label.map_or(NULL_STRING, string_view)
}

pub fn to_bool(value: bool) -> WGPUBool {
    if value { WGPU_TRUE } else { WGPU_FALSE }
}

/// Copies a string view that webgpu.h passed to us.
///
/// # Safety
///
/// `view` must be a valid webgpu.h string view.
pub unsafe fn to_string(view: WGPUStringView) -> String {
    if view.data.is_null() {
        return String::new();
    }
    let bytes = if view.length == WGPU_STRLEN {
        unsafe { core::ffi::CStr::from_ptr(view.data) }.to_bytes()
    } else {
        unsafe { core::slice::from_raw_parts(view.data.cast::<u8>(), view.length) }
    };
    String::from_utf8_lossy(bytes).into_owned()
}
